import Q from 'q';

type configOptions = any;
type configFormat = 'c' | 'json';

interface ConfigInfo {
    appname: string
    servername: string
    host: string
    setdivision: any
    containername: any
    bAppOnly: any
    filename: string
}

declare class TafConfigHelper {
    constructor()

    /** 获取节点的配置内容，返回 TAF 配置项的文本内容 */
    loadConfig(filename: string, configFormat: configFormat): Q.Promise<string>

    /** 获取节点的配置内容，返回 TAF 配置项的 object */
    loadConfigObject (configOptions: configOptions,  configFormat: configFormat): Q.Promise<any>

    /** 加载服务默认的配置项，并且转换为 json */
    loadServerObject (configFormat: configFormat): Q.Promise<JSON>

    /** 把参数转化为 taf.ConfigInfo 实例 */
    getConfigInfoObj (configOptions: configOptions, isForList?: boolean, isListAllFun?: boolean): ConfigInfo

    /** 获取节点的配置列表 */
    getConfigList (configOptions: configOptions): Q.Promise<any>

    /** 获取节点的所有配置项，promise 返回一个 object，key 是文件名，value 是配置内容 */
    getAllConfigData (configOptions: configOptions,  configFormat: configFormat): Q.Promise<any>

    /** 设置 timeout，由于 taf.tafconfig 服务调用响应慢问题，所以默认值为 30s，入参是 ms */
    setTimeout (iTimeout: number): void

    new(): TafConfigHelper
}

export = TafConfigHelper